/**
 * Fourteen new service cities (11 in Indonesia, 3 abroad), and copy fixes so
 * no page implies Arasya only drives between a few named cities.
 *
 * Cities are created only if they don't exist yet. A copy fix is applied only
 * while the field still holds the old text (or, for FAQ items, while the item
 * exists), so anything rewritten in the Studio is left alone.
 * Data: data/2026-09-29-cities.json (generated by scripts/content/apply.py).
 */
import { readFile } from 'node:fs/promises';

const toPath = (segs) =>
  segs.reduce((acc, s) => {
    if (typeof s === 'number') return `${acc}[${s}]`;
    if (typeof s === 'object') return `${acc}[_key=="${s._key}"]`;
    return acc ? `${acc}.${s}` : s;
  }, '');

function read(doc, segs) {
  let node = doc;
  for (const s of segs) {
    if (node == null) return undefined;
    node = typeof s === 'object' ? node.find?.((x) => x?._key === s._key) : node[s];
  }
  return node;
}

export default async function run(client) {
  const data = JSON.parse(await readFile(new URL('./data/2026-09-29-cities.json', import.meta.url), 'utf8'));
  const tx = client.transaction();
  for (const city of data.cities) tx.createIfNotExists(city);

  const ids = [...new Set(data.fixes.map((f) => f.id))];
  const docs = Object.fromEntries((await client.getDocuments(ids)).filter(Boolean).map((d) => [d._id, d]));
  let applied = 0, kept = 0;
  for (const f of data.fixes) {
    const doc = docs[f.id];
    const current = doc && read(doc, f.path);
    if (current === undefined) { kept++; continue; }
    const path = toPath(f.path);
    if (f.old === null && typeof f.new === 'object') {
      tx.patch(f.id, (p) => p.set(Object.fromEntries(Object.entries(f.new).map(([k, v]) => [`${path}.${k}`, v]))));
      applied++;
    } else if (current === f.old) {
      tx.patch(f.id, (p) => p.set({ [path]: f.new }));
      applied++;
    } else kept++;
  }
  await tx.commit({ visibility: 'sync' });
  console.log(`cities: ${data.cities.length} cities ensured; ${applied} copy fixes applied, ${kept} left as edited in the Studio.`);
}
